CustomField.formula:
MAX(0, /* First if completed same day */ IF(DateValue(X3rd_Party_Approval_Started__c) = TODAY(),
/* Adjusts Closed Hour/Minute if it's before or after hours */ IF(Current_Work_Hour__c < 8, 8, IF(Current_Work_Hour__c > 20, 20, Current_Work_Hour__c)) + IF(Current_Work_Hour__c < 8 || Current_Work_Hour__c > 20, 0, Minute(TimeValue(NOW())) / 60) - /* Adjust Created Hour/Minute if it's before or after hours */ ( IF(IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5 < 8, 8, IF(IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5 > 20, 20, IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5)) + IF(IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5 < 8 || IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5 > 20, 0, Minute(TimeValue(X3rd_Party_Approval_Started__c))) / 60 ),
/* If not the same day, calcs hours of first day */ IF(Weekday(DateValue(X3rd_Party_Approval_Started__c)) = 7 || Weekday(DateValue(X3rd_Party_Approval_Started__c)) = 0 || IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5 >= 20, 0,
/* If it's before hours, limit to 8 hours */ IF(IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5 < 8, 8, 20 - (IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5)) + IF(IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5 < 8 || IF(Hour(TimeValue(X3rd_Party_Approval_Started__c)) <= 5, 24, 0) + Hour(TimeValue(X3rd_Party_Approval_Started__c)) - 5 > 20, 0, (Minute(TimeValue(X3rd_Party_Approval_Started__c)) / 60)) ) + /* Calcs days between and converts to hours by multiplying by 8 workhours */ (CASE(WEEKDAY(DateValue(X3rd_Party_Approval_Started__c)), /* This excludes End Dates e.g. Mon Tuesday Wednesday = 1 */ 1, CASE(MOD(Today() - DateValue(X3rd_Party_Approval_Started__c), 7), 1, 0, 2, 1, 3, 2, 4, 3, 5, 4, 6, 5, 0), 2, CASE(MOD(Today() - DateValue(X3rd_Party_Approval_Started__c), 7), 1, 0, 2, 1, 3, 2, 4, 3, 5, 3, 6, 3, 0), 3, CASE(MOD(Today() - DateValue(X3rd_Party_Approval_Started__c), 7), 1, 0, 2, 1, 3, 2, 4, 2, 5, 2, 6, 3, 0), 4, CASE(MOD(Today() - DateValue(X3rd_Party_Approval_Started__c), 7), 1, 0, 2, 1, 3, 1, 4, 1, 5, 2, 6, 3, 0), 5, CASE(MOD(Today() - DateValue(X3rd_Party_Approval_Started__c), 7), 1, 0, 2, 0, 3, 0, 4, 1, 5, 2, 6, 2, 0), 6, CASE(MOD(Today() - DateValue(X3rd_Party_Approval_Started__c), 7), 1, 0, 2, 0, 3, 0, 4, 1, 5, 2, 6, 3, 0), 7, CASE(MOD(Today() - DateValue(X3rd_Party_Approval_Started__c), 7), 1, 0, 2, 0, 3, 0, 4, 1, 5, 2, 6, 2, 0), 999 ) + (FLOOR((Today() - DateValue(X3rd_Party_Approval_Started__c)) / 7) * 5)) * 8 + /* Calcs days at the end */ /* If it's before hours, limit to 8 hours */ IF(Current_Work_Hour__c < 8, 0, IF(Current_Work_Hour__c > 20, 20, Current_Work_Hour__c - 8)) + IF(Current_Work_Hour__c < 8 || Current_Work_Hour__c > 20, 0, (Minute(TimeValue(NOW())) / 60)) ) - Dynamic_Workday_Hours_Unassigned__c )
